import { useEffect, useMemo, useRef, useState } from 'react'
import {
  Activity, ArrowDown, ArrowLeft, ArrowRight, ArrowUp, ArrowUpDown, BarChart3, Box, Check, ChevronDown, ChevronRight,
  CircleStop, Clock3, Copy, Database, File, FileInput, Files, FlaskConical, Folder,
  FolderOpen, Gauge, HardDrive, History, Layers3, LoaderCircle, Menu, MoreHorizontal, Eye, Download,
  Columns3, KeyRound, Network, Pencil, Plus, Minus, RefreshCw, Search, Server, Settings2, ShieldCheck,
  SlidersHorizontal, Sparkles, Trash2, Upload, Wifi, WifiOff, X, Zap,
  TriangleAlert,
} from 'lucide-react'
import { Bar, BarChart, CartesianGrid, Legend, Line, LineChart, ReferenceLine, ResponsiveContainer, Scatter, ScatterChart, Tooltip, XAxis, YAxis, ZAxis } from 'recharts'

const api = async (path, options = {}) => {
  const response = await fetch(path, options)
  const data = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(data.error || `Request failed (${response.status})`)
  return data
}
const cx = (...names) => names.filter(Boolean).join(' ')
const fmtDate = value => value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'
const fmtDuration = seconds => !seconds ? '—' : seconds < 10 ? `${Number(seconds).toFixed(1)} sec` : seconds < 60 ? `${Math.round(seconds)} sec` : `${Math.floor(seconds / 60)}m ${Math.round(seconds % 60)}s`
const list = (value, parser = String) => String(value).split(',').map(x => x.trim()).filter(Boolean).map(parser)
const statusTone = status => ({ completed: 'success', running: 'running', queued: 'running', failed: 'danger', cancelled: 'neutral' }[status] || 'neutral')
const datasetRows = data => data.metadata?.rows || data.metadata?.files?.[0]?.at_least_rows || data.metadata?.files?.[0]?.sampled_rows

function Button({ children, icon: Icon, variant = 'secondary', className, type = 'button', ...props }) {
  return <button type={type} className={cx('button', `button-${variant}`, className)} {...props}>{Icon && <Icon size={16} />}{children}</button>
}
function Badge({ children, tone = 'neutral' }) { return <span className={`badge badge-${tone}`}>{children}</span> }
function Empty({ icon: Icon, title, text, action }) {
  return <div className="empty-state"><div className="empty-icon"><Icon size={24} /></div><h3>{title}</h3><p>{text}</p>{action}</div>
}
function Modal({ title, subtitle, children, onClose, width = '560px' }) {
  return <div className="modal-backdrop" role="presentation" onMouseDown={e => e.target === e.currentTarget && onClose()}><section className="modal" style={{ maxWidth: width }} role="dialog" aria-modal="true"><header><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={18} /></button></header>{children}</section></div>
}
function Toast({ message }) { return message ? <div className="toast"><Check size={16} />{message}</div> : null }
function ConfirmDialog({ title, description, note, confirmLabel = 'Delete', onConfirm, onClose }) {
  const [busy,setBusy]=useState(false),[error,setError]=useState('')
  const confirm=async()=>{setBusy(true);setError('');try{await onConfirm();onClose()}catch(reason){setError(reason.message)}finally{setBusy(false)}}
  return <Modal title={title} subtitle={description} onClose={()=>!busy&&onClose()} width="500px"><div className="confirm-dialog"><div className="confirm-note"><TriangleAlert size={20}/><p>{note}</p></div>{error&&<div className="form-error">{error}</div>}<footer><Button onClick={onClose} disabled={busy}>Cancel</Button><Button variant="danger" icon={busy?LoaderCircle:Trash2} className={busy?'spin-icon':''} onClick={confirm} disabled={busy}>{busy?'Deleting…':confirmLabel}</Button></footer></div></Modal>
}
function Select({ value, onChange, options, ariaLabel }) {
  const [open, setOpen] = useState(false), root = useRef(null)
  const selected = options.find(option => String(option.value) === String(value)) || options[0]
  useEffect(() => { const close = event => { if (!root.current?.contains(event.target)) setOpen(false) }; document.addEventListener('pointerdown', close); return () => document.removeEventListener('pointerdown', close) }, [])
  return <div className={cx('custom-select', open && 'open')} ref={root}>
    <button type="button" className="custom-select-trigger" aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}><span>{selected?.label || 'Select'}</span><ChevronDown size={15}/></button>
    {open && <div className="custom-select-menu" role="listbox">{options.map(option => <button type="button" role="option" aria-selected={String(option.value) === String(value)} className={String(option.value) === String(value) ? 'selected' : ''} key={option.value} onClick={() => { onChange(option.value); setOpen(false) }}><span>{option.label}</span>{String(option.value) === String(value) && <Check size={14}/>}</button>)}</div>}
  </div>
}

export function App() {
  const [projects, setProjects] = useState([])
  const [project, setProject] = useState(null)
  const [tab, setTab] = useState(() => {
    const saved = localStorage.getItem('downstream-studio-tab')
    return ['overview', 'data', 'train', 'history', 'hpc'].includes(saved) ? saved : 'overview'
  })
  const [activeRun, setActiveRun] = useState(null)
  const [newProject, setNewProject] = useState(false)
  const [importer, setImporter] = useState(null)
  const [toast, setToast] = useState('')
  const [sidebar, setSidebar] = useState(false)
  const [projectToDelete, setProjectToDelete] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  const notify = message => { setToast(message); window.clearTimeout(notify.timer); notify.timer = window.setTimeout(() => setToast(''), 2600) }
  const loadProjects = async () => { setLoading(true); setError(''); try { const items = await api('/api/projects'); setProjects(items); const remembered = localStorage.getItem('downstream-studio-project'); if (!project && remembered && items.some(item => item.id === remembered)) await openProject(remembered, true) } catch (reason) { setError(reason.message) } finally { setLoading(false) } }
  const openProject = async (id, keepTab = false) => { setError(''); try { const data = await api(`/api/projects/${id}`); setProject(data); localStorage.setItem('downstream-studio-project', id); if (!keepTab) { setTab('overview'); localStorage.setItem('downstream-studio-tab', 'overview') } setSidebar(false) } catch (reason) { setError(reason.message); notify(reason.message) } }
  useEffect(() => { loadProjects() }, [])
  useEffect(() => { document.title = project ? `${project.name} · Downstream Studio` : 'Downstream Studio' }, [project])
  useEffect(() => {
    if (!project || !project.experiments.some(x => ['queued', 'running'].includes(x.status))) return
    const timer = window.setInterval(() => openProject(project.id, true), 2200)
    return () => window.clearInterval(timer)
  }, [project])

  const createProject = async event => {
    event.preventDefault(); const form = new FormData(event.currentTarget)
    try { const created = await api('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(form)) }); setNewProject(false); await loadProjects(); await openProject(created.id); notify('Project created') } catch (reason) { notify(reason.message) }
  }
  const navigate = (next, run = null) => { setTab(next); setActiveRun(run); if (next !== 'run') localStorage.setItem('downstream-studio-tab', next) }
  const showProjects = () => { setProject(null); localStorage.removeItem('downstream-studio-project'); setTab('overview') }
  const deleteProject = async item => { const result=await api(`/api/projects/${item.id}`,{method:'DELETE'});if(project?.id===item.id)showProjects();await loadProjects();notify(result.recoverable_from?'Project moved to recoverable trash':'Project deleted') }

  return <div className="app-shell">
    <aside className={cx('sidebar', sidebar && 'sidebar-open')}>
      <div className="brand"><div className="brand-symbol"><Network size={19} /></div><div><strong>Downstream</strong><span>Experiment Studio</span></div></div>
      <Button icon={Plus} variant="primary" className="new-project" onClick={() => setNewProject(true)}>New project</Button>
      <div className="side-label">Workspace</div>
      <nav className="project-nav">
        <button className={cx('project-nav-item', !project && 'active')} onClick={showProjects}><Files size={17} /><span>All projects</span><Badge>{projects.length}</Badge></button>
        {projects.map(item => <button key={item.id} className={cx('project-nav-item', project?.id === item.id && 'active')} onClick={() => openProject(item.id)}><span className="project-avatar">{item.name.slice(0, 1).toUpperCase()}</span><span className="project-name">{item.name}</span><ChevronRight size={15} /></button>)}
      </nav>
      <div className="engine-status"><span className="engine-dot" /><div><strong>Local engine</strong><span>Ready for experiments</span></div></div>
    </aside>
    <main className="main-area">
      <button className="mobile-menu mobile-menu-floating icon-button" onClick={() => setSidebar(!sidebar)} aria-label="Open navigation"><Menu size={19} /></button>
      {error && !projects.length ? <div className="page"><Empty icon={CircleStop} title="The workspace could not be loaded" text={error} action={<Button icon={RefreshCw} onClick={loadProjects}>Try again</Button>} /></div> : loading && !projects.length ? <div className="page-loading"><LoaderCircle className="spin" />Loading workspace</div> : project ? <ProjectPage project={project} tab={tab} activeRun={activeRun} navigate={navigate} refresh={() => openProject(project.id, true)} setImporter={setImporter} notify={notify} /> : <ProjectsHome projects={projects} openProject={openProject} create={() => setNewProject(true)} onDelete={setProjectToDelete} />}
    </main>
    {newProject && <Modal title="Create a project" subtitle="Group data, experiments, and results in a reproducible workspace." onClose={() => setNewProject(false)}><form className="modal-form" onSubmit={createProject}><label>Project name<input name="name" placeholder="Interface representation study" required autoFocus /></label><label>Description<textarea name="description" rows="3" placeholder="What do you want to learn from these embeddings?" /></label><footer><Button onClick={() => setNewProject(false)}>Cancel</Button><Button type="submit" variant="primary" icon={Plus}>Create project</Button></footer></form></Modal>}
    {importer && <ImportModal project={project} initialKind={importer} onClose={() => setImporter(null)} onDone={async () => { setImporter(null); await openProject(project.id, true); notify('Dataset connected') }} />}
    {projectToDelete&&<ConfirmDialog title={`Delete ${projectToDelete.name}?`} description="This project will be removed from the workspace." note="Its datasets, experiments, results, and HPC settings will be removed. Project-owned files are moved to recoverable trash; external source files are not changed." confirmLabel="Delete project" onConfirm={()=>deleteProject(projectToDelete)} onClose={()=>setProjectToDelete(null)}/>} 
    <Toast message={toast} />
  </div>
}

function ProjectsHome({ projects, openProject, create, onDelete }) {
  return <div className="page"><div className="page-heading"><div><p className="eyebrow">Representation analysis</p><h1>Projects</h1><p>Organize datasets, probe configurations, and results in focused research workspaces.</p></div><Button variant="primary" icon={Plus} onClick={create}>Create project</Button></div>
    {projects.length ? <div className="project-grid">{projects.map(project => <article className="project-card" key={project.id} onClick={() => openProject(project.id)}><div className="project-card-top"><div className="project-avatar large">{project.name.slice(0, 1).toUpperCase()}</div><div className="project-card-actions-top"><Badge>{project.experiment_count} runs</Badge><button className="icon-button danger-text project-delete" onClick={event=>{event.stopPropagation();onDelete(project)}} aria-label={`Delete ${project.name}`} title="Delete project"><Trash2 size={16}/></button></div></div><h2>{project.name}</h2><p>{project.description || 'No description added yet.'}</p><div className="project-card-meta"><span><Database size={15} />{project.dataset_count} datasets</span><span><Clock3 size={15} />{fmtDate(project.created_at)}</span></div><Button icon={ArrowRight}>Open workspace</Button></article>)}</div> : <Empty icon={FlaskConical} title="Create your first research workspace" text="Connect embeddings and targets, design a probe, then compare what each representation has learned." action={<Button variant="primary" icon={Plus} onClick={create}>Create project</Button>} />}
  </div>
}

function ProjectPage({ project, tab, activeRun, navigate, refresh, setImporter, notify }) {
  const tabs = [{ id: 'overview', label: 'Overview', icon: Gauge }, { id: 'data', label: 'Data', icon: Database }, { id: 'train', label: 'Train', icon: SlidersHorizontal }, { id: 'history', label: 'Experiments', icon: History }, { id: 'hpc', label: 'HPC setup', icon: Server }]
  return <><div className="project-header"><div><div className="project-title-row"><div className="project-avatar large">{project.name.slice(0, 1).toUpperCase()}</div><div><p className="eyebrow">Research project</p><h1>{project.name}</h1></div></div><p>{project.description || 'Downstream representation analysis workspace.'}</p></div><Button variant="primary" icon={Zap} onClick={() => navigate('train')}>New experiment</Button></div>
    <nav className="tabs">{tabs.map(item => <button key={item.id} className={cx(tab === item.id && 'active')} onClick={() => navigate(item.id)}><item.icon size={16} />{item.label}</button>)}</nav>
    <div className="project-content">
      {tab === 'overview' && <Overview project={project} navigate={navigate} setImporter={setImporter} />}
      {tab === 'data' && <DataPage project={project} setImporter={setImporter} refresh={refresh} notify={notify} />}
      {tab === 'train' && <TrainPage project={project} onStarted={async run => { await refresh(); navigate('run', run.id) }} notify={notify} />}
      {tab === 'history' && <HistoryPage project={project} navigate={navigate} refresh={refresh} notify={notify} />}
      {tab === 'hpc' && <HpcPage project={project} notify={notify} />}
      {tab === 'run' && <RunPage id={activeRun} navigate={navigate} refresh={refresh} notify={notify} />}
    </div>
  </>
}

function Overview({ project, navigate, setImporter }) {
  const runs = project.experiments, completed = runs.filter(x => x.status === 'completed').length
  return <div className="overview-grid"><section className="welcome-panel"><div className="welcome-copy"><Badge tone="inverse">Experiment workspace</Badge><h2>Discover what your embeddings know.</h2><p>Train simple probes against interface properties and compare representations with reproducible evidence.</p><Button variant="light" icon={Sparkles} onClick={() => navigate('train')}>Design an experiment</Button></div></section>
    <div className="stats-row"><Stat icon={Database} label="Datasets" value={project.datasets.length} detail="connected sources" /><Stat icon={Activity} label="Experiments" value={runs.length} detail={`${completed} completed`} /><Stat icon={Layers3} label="Models" value={new Set(project.datasets.flatMap(x => x.metadata?.models || [])).size} detail="embedding variants" /></div>
    <section className="panel span-2"><SectionHead eyebrow="Recent activity" title="Latest experiments" action={<Button icon={ArrowRight} onClick={() => navigate('history')}>View all</Button>} />{runs.length ? <div className="run-list">{runs.slice(0, 5).map(run => <RunRow key={run.id} run={run} onOpen={() => navigate('run', run.id)} />)}</div> : <Empty icon={FlaskConical} title="No experiments yet" text="Your first run will appear here with live progress and results." action={<Button variant="primary" icon={Zap} onClick={() => navigate('train')}>Start an experiment</Button>} />}</section>
    <section className="panel"><SectionHead eyebrow="Inputs" title="Connected data" />{project.datasets.length ? project.datasets.map(data => <div className="compact-data" key={data.id}><div className="data-icon"><FileInput size={17} /></div><div><strong>{data.name}</strong><span>{data.kind} · {datasetRows(data)?.toLocaleString() || '—'}+ rows</span></div></div>) : <Empty icon={HardDrive} title="No data connected" text="Add embeddings and targets to begin." action={<Button icon={Plus} onClick={() => setImporter('embeddings')}>Add data</Button>} />}</section>
  </div>
}
function Stat({ icon: Icon, label, value, detail }) { return <article className="stat-card"><div className="stat-icon"><Icon size={18} /></div><div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div></article> }
function SectionHead({ eyebrow, title, action }) { return <div className="section-head"><div>{eyebrow && <p className="eyebrow">{eyebrow}</p>}<h2>{title}</h2></div>{action}</div> }

function DataPage({ project, setImporter, refresh, notify }) {
  const embeddings = project.datasets.filter(x => x.kind === 'embeddings'), targets = project.datasets.filter(x => x.kind === 'targets')
  const [preview, setPreview] = useState(null)
  const [editor, setEditor] = useState(null)
  const [datasetToDelete,setDatasetToDelete]=useState(null)
  const openPreview = async (dataset, file) => { setPreview({ name:dataset.name, loading:true, dataset }); try { setPreview({ ...(await api(`/api/datasets/${dataset.id}/preview${file ? `?file=${encodeURIComponent(file)}` : ''}`)), dataset }) } catch (error) { setPreview({ name:dataset.name, error:error.message, dataset }) } }
  const openEditor = async dataset => { try { setEditor({dataset,...await api(`/api/datasets/${dataset.id}/preview`)}) } catch(error) { notify(error.message); setEditor(null) } }
  const removeDataset = async dataset => { const result=await api(`/api/datasets/${dataset.id}`,{method:'DELETE'}); if(preview?.dataset?.id===dataset.id)setPreview(null);if(editor?.dataset?.id===dataset.id)setEditor(null);await refresh();notify(result.recoverable_from?'Dataset moved to recoverable trash':'Dataset removed from project') }
  return <div><div className="content-heading"><div><p className="eyebrow">Project inputs</p><h2>Data library</h2><p>Manage embedding matrices and interface properties used by this project.</p></div><Button variant="primary" icon={Plus} onClick={() => setImporter('embeddings')}>Connect data</Button></div><div className="data-columns"><DatasetSection title="Embedding datasets" icon={Box} items={embeddings} empty="Connect one or more model embedding CSVs." onAdd={() => setImporter('embeddings')} onPreview={openPreview} onEdit={openEditor} onDelete={setDatasetToDelete}/><DatasetSection title="Target datasets" icon={BarChart3} items={targets} empty="Connect numeric interface properties for probing." onAdd={() => setImporter('targets')} onPreview={openPreview} onEdit={openEditor} onDelete={setDatasetToDelete}/></div>{preview && <DatasetPreview preview={preview} onSelectFile={file => openPreview(preview.dataset, file)} onClose={() => setPreview(null)}/>} {editor&&<DatasetEditor source={editor} onClose={()=>setEditor(null)} onSaved={async()=>{setEditor(null);await refresh();notify('Dataset view updated')}}/>}{datasetToDelete&&<ConfirmDialog title={`Delete ${datasetToDelete.name}?`} description="This dataset will be removed from the project." note="Uploaded files are moved to recoverable trash. Files connected through an external path remain untouched." confirmLabel="Delete dataset" onConfirm={()=>removeDataset(datasetToDelete)} onClose={()=>setDatasetToDelete(null)}/>}</div>
}
function DatasetSection({ title, icon: Icon, items, empty, onAdd, onPreview, onEdit, onDelete }) {
  return <section className="panel"><SectionHead title={title} action={<Button icon={Plus} onClick={onAdd}>Add</Button>} />{items.length ? <div className="dataset-list">{items.map(item => {const remote=item.metadata?.location==='hpc';return <article className="dataset-card" key={item.id}><div className="data-icon"><Icon size={18} /></div><div className="dataset-body"><div><strong>{item.name}</strong><Badge>{remote?'HPC':item.metadata?.view?'edited view':item.metadata?.derived_from?'derived file':item.source_type}</Badge></div><p title={item.path}>{item.path}</p><div className="dataset-facts"><span>{datasetRows(item)?.toLocaleString() || '—'}+ rows</span>{item.kind === 'embeddings' ? <><span>{item.metadata?.models?.length || 0} models</span><span>{item.metadata?.dimensions?.[0] || '—'} dimensions</span></> : <span>{item.metadata?.target_columns?.length || 0} numeric fields</span>}</div></div><div className="dataset-card-actions"><button onClick={() => onPreview(item)} aria-label={`Preview ${item.name}`}><Eye size={16}/><span>Preview</span></button>{!remote&&<button onClick={() => onEdit(item)} aria-label={`Edit ${item.name}`}><Pencil size={15}/><span>Edit</span></button>}<button className="danger-text" onClick={() => onDelete(item)} aria-label={`Delete ${item.name}`}><Trash2 size={15}/><span>Delete</span></button></div></article>})}</div> : <Empty icon={Icon} title={`No ${title.toLowerCase()}`} text={empty} action={<Button icon={Plus} onClick={onAdd}>Connect dataset</Button>} />}</section>
}
function DatasetPreview({ preview, onSelectFile, onClose }) {
  const fileOptions = (preview.files || []).map(file => ({ value:file.path, label:file.name }))
  return <Modal title={preview.name || 'Dataset preview'} subtitle={preview.file ? `${preview.file} · ${(preview.size_bytes/1024/1024).toLocaleString(undefined,{maximumFractionDigits:2})} MB` : 'Inspecting connected data…'} onClose={onClose} width="1180px"><div className="dataset-preview"><div className="dataset-preview-head"><div><p className="eyebrow">Data sample</p><strong>First {preview.rows?.length || 0} rows</strong></div>{fileOptions.length > 1 && <label>Source file<Select ariaLabel="Choose dataset source file" value={preview.file} onChange={onSelectFile} options={fileOptions}/></label>}</div>{preview.loading ? <div className="page-loading"><LoaderCircle className="spin"/>Reading data</div> : preview.error ? <Empty icon={File} title="Preview unavailable" text={preview.error}/> : <CsvPreview artifact={preview}/>}</div></Modal>
}
function DatasetEditor({source,onClose,onSaved}) {
  const dataset=source.dataset,columns=source.editor_columns||source.columns||[],idColumn=source.editor_id_column||dataset.id_column
  const [selected,setSelected]=useState(source.editor_selected||columns),[renames,setRenames]=useState(source.editor_renames||{}),[query,setQuery]=useState(''),[name,setName]=useState(dataset.name),[busy,setBusy]=useState(false),[error,setError]=useState('')
  const shown=columns.filter(column=>column.toLowerCase().includes(query.toLowerCase())),outputColumns=selected.map(column=>renames[column]?.trim()||column),duplicateNames=new Set(outputColumns.filter((name,index)=>outputColumns.indexOf(name)!==index)),valid=selected.includes(idColumn)&&outputColumns.every(Boolean)&&!duplicateNames.size
  const toggle=column=>{if(column===idColumn)return;setSelected(current=>current.includes(column)?current.filter(value=>value!==column):[...current,column])}
  const save=async()=>{setBusy(true);setError('');try{await api(`/api/datasets/${dataset.id}/transform`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,columns:selected,renames,schema_mode:'source'})});onSaved()}catch(reason){setError(reason.message)}finally{setBusy(false)}}
  const previewRows=(source.editor_rows||source.rows||[]).slice(0,6)
  return <Modal title={`Edit ${dataset.name}`} subtitle="Update the active schema used by previews and future experiments. The source CSV files remain unchanged." onClose={onClose} width="1180px"><div className="data-editor"><div className="data-editor-toolbar"><div className="search-field"><Search size={15}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Find a column"/></div><div><span>{selected.length} of {columns.length} columns included</span><Button onClick={()=>setSelected(columns)}>Include all</Button><Button onClick={()=>setSelected([idColumn])}>Exclude optional</Button></div></div><div className="data-editor-layout"><section className="column-editor"><header><span>Include</span><span>Current column</span><span>Output name</span></header><div>{shown.map(column=>{const included=selected.includes(column),output=renames[column]??column,isDuplicate=duplicateNames.has(output.trim());return <div className={cx('column-edit-row',included&&'included')} key={column}><button type="button" className="column-toggle" onClick={()=>toggle(column)} disabled={column===idColumn} aria-label={`${included?'Exclude':'Include'} ${column}`}><span className="check-box">{included&&<Check size={12}/>}</span></button><div><strong>{column}</strong>{column===idColumn&&<small>ID column · required</small>}</div><input value={output} disabled={!included||column===idColumn} className={isDuplicate?'invalid':''} onChange={event=>setRenames(current=>({...current,[column]:event.target.value}))} aria-label={`Rename ${column}`}/></div>})}</div></section><aside className="schema-preview"><div><p className="eyebrow">Active schema</p><h3>{outputColumns.length} columns</h3><p>This schema is used automatically by the Train tab. No duplicate dataset is created.</p></div><div className="schema-chips">{outputColumns.slice(0,40).map((column,index)=><span className={duplicateNames.has(column)?'invalid':''} key={`${column}-${index}`}>{column}</span>)}{outputColumns.length>40&&<span>+{outputColumns.length-40} more</span>}</div><div className="mini-data-preview"><table><thead><tr>{selected.slice(0,6).map(column=><th key={column}>{renames[column]?.trim()||column}</th>)}</tr></thead><tbody>{previewRows.map((row,index)=><tr key={index}>{selected.slice(0,6).map(column=><td key={column}>{formatArtifactCell(row[column])}</td>)}</tr>)}</tbody></table></div></aside></div><footer className="data-editor-footer"><label>Dataset name<input value={name} onChange={event=>setName(event.target.value)} required/></label><div>{error&&<span className="editor-error">{error}</span>}<Button onClick={onClose}>Cancel</Button><Button variant="primary" icon={busy?LoaderCircle:Columns3} className={busy?'spin-icon':''} disabled={busy||!valid||!name.trim()} onClick={save}>{busy?'Applying changes…':'Apply changes'}</Button></div></footer></div></Modal>
}

function ImportModal({ project, initialKind, onClose, onDone }) {
  const [kind, setKind] = useState(initialKind), [mode, setMode] = useState('browse'), [path, setPath] = useState(''), [browser, setBrowser] = useState(null), [file, setFile] = useState(null), [busy, setBusy] = useState(false), [error, setError] = useState('')
  const browse = async next => { try { setError(''); const endpoint=mode==='hpc'?`/api/projects/${project.id}/hpc/files`:'/api/files';setBrowser(await api(`${endpoint}${next ? `?path=${encodeURIComponent(next)}` : ''}`)) } catch (e) { setError(e.message);setBrowser(null) } }
  useEffect(() => { if(mode!=='upload'){setPath('');setBrowser(null);browse()} }, [mode])
  const submit = async event => { event.preventDefault(); setBusy(true); setError(''); try { if (mode === 'upload') { if (!file) throw new Error('Choose a CSV file first'); await api(`/api/projects/${project.id}/datasets/upload`, { method: 'POST', headers: { 'X-Dataset-Kind': kind, 'X-Filename': encodeURIComponent(file.name), 'X-Dataset-Name': encodeURIComponent(event.currentTarget.elements.name.value || file.name), 'X-Id-Column': 'id', 'X-Feature-Prefix': 'f' }, body: file }) } else { if (!path) throw new Error('Select a CSV file or enter a path'); await api(`/api/projects/${project.id}/datasets/${mode==='hpc'?'hpc':'path'}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind, path, name: event.currentTarget.elements.name.value, id_column: 'id', feature_prefix: 'f' }) }) } onDone() } catch (e) { setError(e.message) } finally { setBusy(false) } }
  return <Modal title="Connect a dataset" subtitle="Reference local or HPC files without copying large inputs." onClose={onClose} width="720px"><form className="modal-form" onSubmit={submit}><div className="segmented"><button type="button" className={kind === 'embeddings' ? 'active' : ''} onClick={() => setKind('embeddings')}><Box size={16} />Embeddings</button><button type="button" className={kind === 'targets' ? 'active' : ''} onClick={() => setKind('targets')}><BarChart3 size={16} />Targets</button></div><div className="segmented subtle"><button type="button" className={mode === 'browse' ? 'active' : ''} onClick={() => setMode('browse')}><FolderOpen size={16} />Local path</button><button type="button" className={mode === 'hpc' ? 'active' : ''} onClick={() => setMode('hpc')}><Server size={16} />HPC path</button><button type="button" className={mode === 'upload' ? 'active' : ''} onClick={() => setMode('upload')}><Upload size={16} />Upload CSV</button></div>{mode !== 'upload' ? <FileBrowser browser={browser} path={path} setPath={setPath} browse={browse} /> : <label className="upload-zone"><Upload size={24} /><strong>{file ? file.name : 'Choose a CSV file'}</strong><span>{file ? `${(file.size / 1024 / 1024).toFixed(2)} MB` : 'Drag and drop is supported by your browser'}</span><input type="file" accept=".csv,text/csv" onChange={e => setFile(e.target.files[0])} /></label>}<label>Dataset name <span className="optional">optional</span><input name="name" placeholder={kind === 'embeddings' ? 'AF model embeddings' : 'Interface features'} /></label>{mode==='hpc'&&<div className="form-note"><ShieldCheck size={16}/><span>Only schema and sample rows are transferred. The complete dataset remains on HPC storage.</span></div>}{error && <div className="form-error">{error}</div>}<footer><Button type="button" onClick={onClose}>Cancel</Button><Button type="submit" variant="primary" icon={kind === 'embeddings' ? Box : BarChart3} disabled={busy}>{busy ? 'Inspecting data…' : 'Connect dataset'}</Button></footer></form></Modal>
}
function FileBrowser({ browser, path, setPath, browse }) {
  if (!browser) return <div className="browser-loading"><LoaderCircle className="spin" />Reading folders</div>
  return <div className="file-browser"><div className="browser-toolbar">{browser.parent && <button type="button" className="icon-button" onClick={() => browse(browser.parent)}><ArrowLeft size={17} /></button>}<div className="path-field"><Folder size={15} /><input value={path || browser.path || ''} onChange={e => setPath(e.target.value)} placeholder="Select a CSV or paste its path" /></div></div>{!browser.path ? <div className="file-list">{browser.roots.map(root => <button type="button" key={root.path} onClick={() => browse(root.path)}><Folder size={17} /><span>{root.name}</span><ChevronRight size={15} /></button>)}</div> : <div className="file-list">{browser.entries.map(entry => <button type="button" className={path === entry.path ? 'selected' : ''} key={entry.path} onDoubleClick={() => entry.type === 'directory' ? browse(entry.path) : setPath(entry.path)} onClick={() => entry.type === 'directory' ? browse(entry.path) : setPath(entry.path)}>{entry.type === 'directory' ? <Folder size={17} /> : <File size={17} />}<span>{entry.name}</span>{entry.type === 'directory' ? <ChevronRight size={15} /> : <small>{(entry.size_bytes / 1024 / 1024).toFixed(1)} MB</small>}</button>)}</div>}</div>
}

const defaultLayers = [{ units: 256, activation: 'gelu' }, { units: 128, activation: 'gelu' }]
function TrainPage({ project, onStarted, notify }) {
  const embeddings = project.datasets.filter(x => x.kind === 'embeddings'), targets = project.datasets.filter(x => x.kind === 'targets')
  const [embeddingId, setEmbeddingId] = useState(embeddings[0]?.id || ''), [targetId, setTargetId] = useState(targets[0]?.id || '')
  const embedding = embeddings.find(x => x.id === embeddingId), target = targets.find(x => x.id === targetId)
  const [models, setModels] = useState(embedding?.metadata?.models || []), [fields, setFields] = useState(target?.metadata?.target_columns?.slice(0, 1) || [])
  const [probe, setProbe] = useState('linear'), [linearWidth, setLinearWidth] = useState(0), [layers, setLayers] = useState(defaultLayers), [dropout, setDropout] = useState(.1)
  const [name, setName] = useState('Interface feature probes')
  const [fractions, setFractions] = useState([0.1, 0.25, 0.5])
  const [epochs, setEpochs] = useState([25, 50, 100])
  const [batch, setBatch] = useState(4096), [device, setDevice] = useState('auto')
  const [learningRate, setLearningRate] = useState(0.001), [weightDecay, setWeightDecay] = useState(0.0001), [seed, setSeed] = useState(42)
  const [savePredictions, setSavePredictions] = useState(true), [advanced, setAdvanced] = useState(false), [busy, setBusy] = useState(false)
  const [executionTarget,setExecutionTarget]=useState('local'),[partition,setPartition]=useState('barnard'),[cpus,setCpus]=useState(4),[memoryGb,setMemoryGb]=useState(16),[hours,setHours]=useState(8),[gpus,setGpus]=useState(0),[account,setAccount]=useState('')
  useEffect(() => setModels(embedding?.metadata?.models || []), [embeddingId])
  useEffect(() => setFields(target?.metadata?.target_columns?.slice(0, 1) || []), [targetId])
  useEffect(()=>{if(embedding?.metadata?.location==='hpc'&&target?.metadata?.location==='hpc'){setExecutionTarget('hpc');const cluster=embedding.metadata.cluster||'barnard';setPartition(cluster);setGpus(cluster==='capella'?1:0);setDevice(cluster==='capella'?'cuda':'cpu')}},[embeddingId,targetId])
  if (!embeddings.length || !targets.length) return <Empty icon={Database} title="Connect both input types first" text="Training requires an embeddings dataset and a numeric target dataset." />
  const evaluations = models.length * fields.length * fractions.length * epochs.length
  const start = async () => { if (!models.length || !fields.length || !fractions.length || !epochs.length) return notify('Select at least one model, target, data fraction, and training duration'); setBusy(true); try { const body = { name, execution_target:executionTarget, slurm:{partition,cpus:Number(cpus),memory_gb:Number(memoryGb),hours:Number(hours),gpus:Number(gpus),account}, embeddings_dataset_id: embeddingId, targets_dataset_id: targetId, embedding_models: models, target_columns: fields, probes: [probe], linear_width: linearWidth, layers, train_fractions: fractions, epochs, batch_size: Number(batch), learning_rate: Number(learningRate), weight_decay: Number(weightDecay), hidden_dim: layers[0]?.units || 128, dropout: Number(dropout), seed: Number(seed), device, save_predictions: savePredictions, id_column: 'id', feature_prefix: 'f', log_every: 10 }; const run = await api(`/api/projects/${project.id}/experiments`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body) }); notify(executionTarget==='hpc'?'Slurm job is being submitted':'Experiment started'); onStarted(run) } catch (e) { notify(e.message) } finally { setBusy(false) } }
  return <div className="train-layout"><div className="builder"><div className="content-heading"><div><p className="eyebrow">Experiment builder</p><h2>Design a downstream probe</h2><p>Configure what to test and how the probe should learn.</p></div></div><BuilderSection number="01" title="Select information" subtitle="Choose representations and interface properties"><div className="form-grid two"><label>Embeddings dataset<Select value={embeddingId} onChange={setEmbeddingId} options={embeddings.map(x => ({value:x.id,label:x.name}))} /></label><label>Target dataset<Select value={targetId} onChange={setTargetId} options={targets.map(x => ({value:x.id,label:x.name}))} /></label></div><ChoiceGroup title="Embedding models" values={embedding?.metadata?.models || []} selected={models} setSelected={setModels} /><ChoiceGroup title="Target fields" values={target?.metadata?.target_columns || []} selected={fields} setSelected={setFields} searchable /></BuilderSection>
    <BuilderSection number="02" title="Build the probe" subtitle="Configure the architecture and see every change immediately"><div className="probe-switch" role="radiogroup" aria-label="Probe type"><label className={probe === 'linear' ? 'active' : ''}><input type="radio" name="probe-type" checked={probe === 'linear'} onChange={() => setProbe('linear')} /><div><Network size={18} /><strong>Linear probe</strong></div><span>Measures information accessible through a linear mapping.</span></label><label className={probe === 'mlp' ? 'active' : ''}><input type="radio" name="probe-type" checked={probe === 'mlp'} onChange={() => setProbe('mlp')} /><div><Layers3 size={18} /><strong>Custom MLP</strong></div><span>Learns nonlinear combinations of embedding dimensions.</span></label></div>{probe === 'linear' ? <LinearEditor width={linearWidth} setWidth={setLinearWidth} dimension={embedding?.metadata?.dimensions?.[0]} /> : <LayerEditor layers={layers} setLayers={setLayers} dropout={dropout} setDropout={setDropout} dimension={embedding?.metadata?.dimensions?.[0]} />}</BuilderSection>
    <BuilderSection number="03" title="Configure training" subtitle="Each selected fraction and duration creates a separate evaluation"><div className="preset-row">{[
      {name:'Quick check',detail:'1 fraction · 1 duration',fractions:[0.5],epochs:[25],batch:4096},
      {name:'Balanced',detail:'3 fractions · 2 durations',fractions:[0.1,0.25,0.5],epochs:[50,100],batch:4096},
      {name:'Thorough',detail:'4 fractions · 3 durations',fractions:[0.1,0.25,0.5,0.8],epochs:[50,100,250],batch:2048},
    ].map(p => <button key={p.name} onClick={() => { setFractions(p.fractions); setEpochs(p.epochs); setBatch(p.batch) }}><strong>{p.name}</strong><span>{p.detail}</span></button>)}</div>
      <TrainingVariants title="Training data per evaluation" description="Compare how much labeled data the probe needs." options={[[0.1,'10%'],[0.25,'25%'],[0.5,'50%'],[0.8,'80%']]} selected={fractions} setSelected={setFractions} />
      <TrainingVariants title="Training duration per evaluation" description="25 and 50 epochs means two independent probes are trained: one for 25 epochs and another for 50." options={[[25,'25 epochs'],[50,'50 epochs'],[100,'100 epochs'],[250,'250 epochs'],[500,'500 epochs'],[1500,'1,500 epochs']]} selected={epochs} setSelected={setEpochs} />
      <div className="form-grid two training-basics"><label>Batch size<Select value={batch} onChange={value => setBatch(Number(value))} options={[{value:256,label:'256 — low memory'},{value:512,label:'512'},{value:1024,label:'1,024'},{value:2048,label:'2,048'},{value:4096,label:'4,096 — faster throughput'}]} /><small>Samples processed before one optimizer update.</small></label><label>Compute device<Select value={device} onChange={setDevice} options={[{value:'auto',label:'Auto-select fastest available'},{value:'cpu',label:'CPU'},{value:'mps',label:'Apple GPU (MPS)'},{value:'cuda',label:'NVIDIA GPU (CUDA)'}]} /><small>Auto is recommended for portable configurations.</small></label></div>
      <div className="execution-panel"><div className="execution-choice"><div><strong>Execution location</strong><p>Remote jobs read HPC paths directly and continue after Studio closes.</p></div><div className="segmented subtle"><button type="button" className={executionTarget==='local'?'active':''} onClick={()=>setExecutionTarget('local')}><HardDrive size={15}/>Local</button><button type="button" className={executionTarget==='hpc'?'active':''} onClick={()=>setExecutionTarget('hpc')}><Server size={15}/>HPC via Slurm</button></div></div>{executionTarget==='hpc'&&<div className="slurm-grid"><label>Partition<Select value={partition} onChange={value=>{setPartition(value);if(value==='barnard'){setGpus(0);setDevice('cpu')}else{setGpus(1);setDevice('cuda')}}} options={[{value:'barnard',label:'Barnard — CPU'},{value:'capella',label:'Capella — GPU'}]}/></label><label>CPU cores<input type="number" min="1" max="64" value={cpus} onChange={e=>setCpus(e.target.value)}/></label><label>Memory (GB)<input type="number" min="1" max="512" value={memoryGb} onChange={e=>setMemoryGb(e.target.value)}/></label><label>Maximum hours<input type="number" min="1" max="168" value={hours} onChange={e=>setHours(e.target.value)}/></label>{partition==='capella'&&<label>GPUs<input type="number" min="1" max="8" value={Math.max(1,gpus)} onChange={e=>setGpus(e.target.value)}/></label>}<label>Slurm account <span className="optional">optional</span><input value={account} onChange={e=>setAccount(e.target.value)} placeholder="Use cluster default"/></label></div>}</div>
      <button className="advanced-toggle" onClick={() => setAdvanced(!advanced)}><Settings2 size={15} />Advanced optimizer settings<ChevronDown size={15} className={advanced ? 'rotate' : ''} /></button>{advanced && <div className="advanced-panel"><LearningRateControl value={learningRate} onChange={setLearningRate}/><div className="form-grid two optimizer-secondary"><label>Weight decay<Select value={weightDecay} onChange={value => setWeightDecay(Number(value))} options={[{value:0,label:'None'},{value:.00001,label:'0.00001'},{value:.0001,label:'0.0001 — recommended'},{value:.001,label:'0.001'},{value:.01,label:'0.01'}]} /></label><label>Random seed<input type="number" min="0" step="1" value={seed} onChange={e => setSeed(e.target.value)} /></label></div><label className="checkbox-row"><input type="checkbox" checked={savePredictions} onChange={e => setSavePredictions(e.target.checked)} /><span><strong>Save test predictions</strong><small>Writes per-interface predictions for the final configurations.</small></span></label></div>}</BuilderSection></div>
    <aside className="run-sidebar"><div className="run-summary-card"><div className="summary-heading"><div className="summary-icon"><Zap size={18} /></div><div><span>Experiment plan</span><strong>{evaluations.toLocaleString()} evaluations</strong></div></div><dl><div><dt>Probe</dt><dd>{probe === 'linear' ? `Linear${linearWidth ? ` · ${linearWidth}` : ''}` : `MLP · ${layers.map(x => x.units).join(' / ')}`}</dd></div><div><dt>Models × targets</dt><dd>{models.length} × {fields.length}</dd></div><div><dt>Data variants</dt><dd>{fractions.map(x => `${x*100}%`).join(', ') || 'none'}</dd></div><div><dt>Duration variants</dt><dd>{epochs.join(', ') || 'none'} epochs</dd></div><div><dt>Runs on</dt><dd>{executionTarget==='hpc'?`${partition} · Slurm`:'this computer'}</dd></div><div><dt>Device</dt><dd>{device}</dd></div></dl><label>Experiment name<input value={name} onChange={e => setName(e.target.value)} /></label><Button variant="primary" icon={busy ? LoaderCircle : Zap} className={busy ? 'spin-icon' : ''} disabled={busy || !evaluations} onClick={start}>{busy ? 'Starting…' : executionTarget==='hpc'?'Submit Slurm job':'Start training'}</Button><p className="summary-note"><Clock3 size={14} />{executionTarget==='hpc'?'The job continues in Slurm even when Studio is closed.':'Training continues in the background. You can safely leave this page.'}</p></div></aside></div>
}
function BuilderSection({ number, title, subtitle, children }) { return <section className="builder-section"><div className="builder-title"><span>{number}</span><div><h3>{title}</h3><p>{subtitle}</p></div></div>{children}</section> }
function LearningRateControl({ value, onChange }) {
  const safeValue = Math.min(.1, Math.max(.00001, Number(value) || .001))
  const sliderValue = Math.log10(safeValue)
  const updateInput = event => { const next=Number(event.target.value); if (Number.isFinite(next)) onChange(Math.min(.1,Math.max(.00001,next))) }
  return <div className="learning-rate-control"><div className="learning-rate-heading"><div><strong>Learning rate</strong><small>Controls the size of each optimizer update. The slider uses a logarithmic scale.</small></div><label><span>Exact value</span><input type="number" min="0.00001" max="0.1" step="0.00001" value={value} onChange={updateInput}/></label></div><input className="learning-rate-slider" type="range" min="-5" max="-1" step="0.05" value={sliderValue} onChange={event=>onChange(Number((10**Number(event.target.value)).toPrecision(5)))}/><div className="learning-rate-scale"><span>0.00001</span><span>0.0001</span><span className="recommended">0.001 recommended</span><span>0.01</span><span>0.1</span></div></div>
}
function ChoiceGroup({ title, values, selected, setSelected, searchable }) { const [query, setQuery] = useState(''); const shown = values.filter(x => x.toLowerCase().includes(query.toLowerCase())); const allSelected=values.length>0&&values.every(value=>selected.includes(value)); const toggle=value=>setSelected(current=>current.includes(value)?current.filter(item=>item!==value):[...current,value]); return <div className="choice-block"><div className="choice-title"><strong>{title}</strong><button type="button" onClick={() => setSelected(allSelected ? [] : [...values])}>{allSelected?'Clear all':'Select all'}</button></div>{searchable && values.length > 8 && <div className="search-field choice-filter"><Search size={15} /><input placeholder="Filter fields" value={query} onChange={e => setQuery(e.target.value)} /></div>}<div className="choice-grid">{shown.map(value => <button type="button" key={value} className={selected.includes(value) ? 'selected' : ''} onClick={() => toggle(value)}><span className="check-box">{selected.includes(value) && <Check size={12} />}</span>{value}</button>)}</div></div> }
function TrainingVariants({ title, description, options, selected, setSelected }) { const toggle = value => setSelected(selected.includes(value) ? selected.filter(x => x !== value) : [...selected, value].sort((a,b) => a-b)); return <div className="training-variant"><div><strong>{title}</strong><p>{description}</p></div><div className="variant-options">{options.map(([value,label]) => <label key={value} className={selected.includes(value) ? 'selected' : ''}><input type="checkbox" checked={selected.includes(value)} onChange={() => toggle(value)} /><span className="check-box">{selected.includes(value) && <Check size={12} />}</span>{label}</label>)}</div></div> }
function LinearEditor({ width, setWidth, dimension }) { return <div className="architecture-panel"><Architecture nodes={[{ type: 'input', label: 'Embedding', value: `${dimension || 'd'} dimensions` }, ...(width ? [{ type: 'hidden', label: 'Linear bottleneck', value: `${width} neurons` }] : []), { type: 'output', label: 'Regression', value: '1 output' }]} /><div className="parameter-row"><div><strong>Bottleneck width</strong><span>Set to 0 for direct linear regression.</span></div><NumberControl value={width} setValue={setWidth} step={16} min={0} /></div></div> }
function LayerEditor({ layers, setLayers, dropout, setDropout, dimension }) { const update = (i, field, value) => setLayers(layers.map((x, n) => n === i ? { ...x, [field]: value } : x)); const activations=[{value:'relu',label:'ReLU'},{value:'gelu',label:'GELU'},{value:'silu',label:'SiLU'},{value:'tanh',label:'Tanh'},{value:'leaky_relu',label:'Leaky ReLU'},{value:'identity',label:'None (identity)'}]; return <div className="architecture-panel"><Architecture nodes={[{ type:'input',label:'Embedding',value:`${dimension || 'd'} dimensions` },...layers.map((x,i)=>({type:'hidden',label:`Hidden ${i+1}`,value:`${x.units} · ${x.activation}`})),{type:'output',label:'Regression',value:'1 output'}]} /><div className="layer-list">{layers.map((layer,i) => <section className="layer-control" key={i}><header><div><span className="layer-number">{i+1}</span><strong>Hidden layer {i+1}</strong></div><button className="icon-button danger-text" onClick={() => layers.length>1 && setLayers(layers.filter((_,n)=>n!==i))} aria-label={`Remove hidden layer ${i+1}`} disabled={layers.length===1}><Trash2 size={16}/></button></header><div className="layer-fields"><label>Neurons<NumberControl value={layer.units} setValue={value=>update(i,'units',Math.min(8192,Math.max(1,value)))} step={32} min={1}/></label><label>Activation function<Select value={layer.activation} onChange={value=>update(i,'activation',value)} options={activations}/></label></div></section>)}</div><div className="layer-footer"><Button icon={Plus} onClick={()=>setLayers([...layers,{units:Math.max(16,Math.floor(layers.at(-1).units/2)),activation:'gelu'}])}>Add hidden layer</Button><label className="range-field"><span><strong>Dropout</strong><output>{Math.round(Number(dropout)*100)}%</output></span><input type="range" min="0" max="0.9" step="0.05" value={dropout} onChange={e=>setDropout(Number(e.target.value))}/><small>Randomly disables neurons during training to reduce overfitting.</small></label></div></div> }
function NumberControl({ value, setValue, step, min }) { const number=Number(value); return <div className="number-control"><button type="button" aria-label={`Decrease by ${step}`} disabled={number<=min} onClick={()=>setValue(Math.max(min,number-step))}><Minus size={14}/></button><input type="number" inputMode="numeric" min={min} step={step} value={value} aria-label="Numeric value" onChange={e=>setValue(Number(e.target.value))}/><button type="button" aria-label={`Increase by ${step}`} onClick={()=>setValue(number+step)}><Plus size={14}/></button></div> }
function Architecture({ nodes }) { return <div className="architecture">{nodes.map((node, index) => <div className="architecture-item" key={`${node.label}-${index}`}>{index > 0 && <div className="connector"><ArrowRight size={16} /></div>}<div className={`architecture-node ${node.type}`}><div>{node.type === 'input' ? <Box size={17} /> : node.type === 'output' ? <Activity size={17} /> : <Layers3 size={17} />}</div><span>{node.label}</span><strong>{node.value}</strong></div></div>)}</div> }

function HpcPage({ project, notify }) {
  const [profile,setProfile]=useState(null),[password,setPassword]=useState(''),[savePassword,setSavePassword]=useState(true),[busy,setBusy]=useState(false)
  const load=async()=>{try{setProfile(await api(`/api/projects/${project.id}/hpc`))}catch(error){notify(error.message)}}
  useEffect(()=>{load()},[project.id])
  const update=(key,value)=>setProfile(current=>({...current,[key]:value}))
  const connect=async event=>{event.preventDefault();setBusy(true);try{const connected=await api(`/api/projects/${project.id}/hpc/test`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...profile,password,save_password:savePassword})});setProfile(connected);setPassword('');notify(connected.save_warning||'HPC connection verified')}catch(error){await load();notify(error.message)}finally{setBusy(false)}}
  const deploy=async()=>{setBusy(true);try{const deployed=await api(`/api/projects/${project.id}/hpc/deploy`,{method:'POST'});setProfile(current=>({...current,...deployed,worker_version:deployed.version}));notify(`Worker ${deployed.version} deployed`)}catch(error){notify(error.message)}finally{setBusy(false)}}
  const disconnect=async()=>{setBusy(true);try{setProfile(await api(`/api/projects/${project.id}/hpc/disconnect`,{method:'POST'}));setPassword('');notify('HPC session disconnected')}catch(error){notify(error.message)}finally{setBusy(false)}}
  const forget=async()=>{setBusy(true);try{setProfile(await api(`/api/projects/${project.id}/hpc/forget`,{method:'POST'}));setPassword('');notify('Saved HPC password removed')}catch(error){notify(error.message)}finally{setBusy(false)}}
  if(!profile)return <div className="page-loading"><LoaderCircle className="spin"/>Loading HPC setup</div>
  const connected=profile.last_status==='connected'&&profile.credential_available
  const hosts=(profile.allowed_hosts||[]).map(host=>({value:host,label:host.replace('.hpc.tu-dresden.de','')}))
  const passwordAuth=profile.auth_method==='password',workerVersion=profile.worker_version||profile.version
  return <div><div className="content-heading"><div><p className="eyebrow">Remote execution</p><h2>HPC connection</h2><p>Submit isolated Slurm jobs from Studio without running a web service on the cluster.</p></div><Badge tone={connected?'success':profile.last_status==='failed'?'danger':'neutral'}>{connected?'Connected':profile.last_status==='failed'?'Connection failed':'Not connected'}</Badge></div><div className="hpc-layout"><form className="panel hpc-form" onSubmit={connect}><SectionHead eyebrow="Outbound SSH" title="TU Dresden HPC"/><div className="hpc-host-row"><label>Login node<Select value={profile.host} onChange={value=>update('host',value)} options={hosts}/></label><label>SSH port<input type="number" min="1" max="65535" value={profile.port} onChange={event=>update('port',Number(event.target.value))}/></label></div><label>ZIH username<input autoComplete="username" value={profile.username} onChange={event=>update('username',event.target.value)} placeholder="e.g. your-zih-username" required/></label><label>Authentication<Select value={profile.auth_method||'agent'} onChange={value=>update('auth_method',value)} options={[{value:'agent',label:'SSH agent / local key — recommended'},{value:'password',label:'Password from system keychain'}]}/><small>SSH-agent authentication keeps credentials out of Studio and the project database.</small></label>{passwordAuth&&<><label>Password<input type="password" autoComplete="current-password" value={password} onChange={event=>setPassword(event.target.value)} placeholder={profile.credential_saved?'Saved in your system credential store':'Your ZIH password'} required={!profile.credential_saved}/></label><label className="checkbox-row credential-checkbox"><input type="checkbox" checked={savePassword} onChange={event=>setSavePassword(event.target.checked)}/><span><strong>Remember password securely</strong><small>Save it in the operating system credential store.</small></span></label></>}<label>Remote Python<input value={profile.remote_python||'python3'} onChange={event=>update('remote_python',event.target.value)} placeholder="python3"/><small>Must be Python 3.10 or newer and able to create a virtual environment.</small></label><div className="hpc-actions"><Button type="submit" variant="primary" icon={busy?LoaderCircle:Wifi} className={busy?'spin-icon':''} disabled={busy||!profile.username||(passwordAuth&&!password&&!profile.credential_saved)}>{busy?'Working…':connected?'Test connection':'Connect securely'}</Button>{connected&&<Button icon={WifiOff} onClick={disconnect} disabled={busy}>Disconnect</Button>}{passwordAuth&&profile.credential_saved&&<Button icon={Trash2} onClick={forget} disabled={busy}>Forget password</Button>}</div></form><aside className="hpc-side"><section className="panel connection-card"><div className={cx('connection-symbol',connected&&'connected')}>{connected?<ShieldCheck size={23}/>:<Server size={23}/>}</div><p className="eyebrow">Connection status</p><h3>{connected?'Slurm gateway ready':'Set up secure access'}</h3><p>{profile.last_message||'Configure an outbound SSH connection to a login node.'}</p><dl><div><dt>Host</dt><dd>{profile.host}</dd></div><div><dt>Authentication</dt><dd>{passwordAuth?'System keychain':'SSH agent'}</dd></div><div><dt>HPC web service</dt><dd>None</dd></div><div><dt>Worker</dt><dd>{workerVersion||'Not deployed'}</dd></div></dl>{profile.last_tested_at&&<small>Last tested {fmtDate(profile.last_tested_at)}</small>}</section><section className="hpc-note"><ShieldCheck size={18}/><div><strong>Outbound-only design</strong><p>Studio uploads validated job files, calls sbatch, polls Slurm, and retrieves bounded result summaries. No web port is opened on HPC.</p></div></section>{connected&&<section className="panel worker-deploy"><p className="eyebrow">Compute package</p><h3>{workerVersion?'Worker installed':'Deploy the worker'}</h3><p>Studio creates <code>~/.downstream-studio</code>, uploads a versioned source bundle, and installs it into a private virtual environment.</p><Button variant="primary" icon={busy?LoaderCircle:Upload} className={busy?'spin-icon':''} onClick={deploy} disabled={busy}>{busy?'Deploying…':workerVersion?'Update worker':'Deploy worker'}</Button></section>}</aside></div></div>
}

function HistoryPage({ project, navigate, refresh, notify }) {
  const [query, setQuery] = useState(''), [status, setStatus] = useState('all')
  const [runToDelete,setRunToDelete]=useState(null)
  const runs = project.experiments.filter(x => (status === 'all' || x.status === status) && x.name.toLowerCase().includes(query.toLowerCase()))
  const remove = async run => { await api(`/api/experiments/${run.id}`, { method: 'DELETE' }); notify('Experiment moved to trash'); await refresh() }
  return <div><div className="content-heading"><div><p className="eyebrow">Project timeline</p><h2>Experiment history</h2><p>Review, compare, and manage every training run.</p></div><Button variant="primary" icon={Plus} onClick={() => navigate('train')}>New experiment</Button></div><section className="panel"><div className="table-toolbar"><div className="search-field"><Search size={16} /><input placeholder="Search experiments" value={query} onChange={e => setQuery(e.target.value)} /></div><Select value={status} onChange={setStatus} ariaLabel="Filter experiments by status" options={[{value:'all',label:'All statuses'},{value:'completed',label:'Completed'},{value:'running',label:'Running'},{value:'failed',label:'Failed'},{value:'cancelled',label:'Cancelled'}]}/></div>{runs.length ? <div className="experiment-table"><div className="experiment-table-head"><span>Experiment</span><span>Configuration</span><span>Status</span><span>Created</span><span /></div>{runs.map(run => <div className="experiment-row" key={run.id} onClick={() => navigate('run', run.id)}><div><div className="run-avatar"><FlaskConical size={16} /></div><span><strong>{run.name}</strong><small>#{run.id}</small></span></div><div><strong>{run.config?.probes?.join(' + ')}</strong><small>{run.config?.target_columns?.join(', ')}</small></div><div><Badge tone={statusTone(run.status)}>{run.status}</Badge></div><div><strong>{fmtDate(run.created_at)}</strong><small>{run.finished_at ? fmtDuration((new Date(run.finished_at) - new Date(run.started_at)) / 1000) : '—'}</small></div><div className="row-actions"><button className="icon-button" title="Copy configuration" onClick={e => { e.stopPropagation(); navigate('train'); notify('Open the builder to configure a new run') }}><Copy size={16} /></button><button className="icon-button danger-text" title="Delete experiment" onClick={e => { e.stopPropagation(); setRunToDelete(run) }}><Trash2 size={16} /></button><ChevronRight size={16} /></div></div>)}</div> : <Empty icon={History} title="No experiments found" text="Try changing your filters or start a new experiment." />}</section>{runToDelete&&<ConfirmDialog title={`Delete ${runToDelete.name}?`} description="This experiment will be removed from the history." note="Its logs, predictions, metrics, and other result files will be moved to recoverable trash." confirmLabel="Delete experiment" onConfirm={()=>remove(runToDelete)} onClose={()=>setRunToDelete(null)}/>}</div>
}
function RunRow({ run, onOpen }) { return <button className="run-row" onClick={onOpen}><div className="run-avatar"><FlaskConical size={16} /></div><div><strong>{run.name}</strong><span>{run.config?.target_columns?.join(', ') || 'No targets'}</span></div><Badge tone={statusTone(run.status)}>{run.status}</Badge><span className="run-date">{fmtDate(run.created_at)}</span><ChevronRight size={16} /></button> }

function RunPage({ id, navigate, refresh, notify }) {
  const [run, setRun] = useState(null), [results, setResults] = useState(null)
  const [resultTarget, setResultTarget] = useState(''), [showRawLog, setShowRawLog] = useState(false)
  const [artifact, setArtifact] = useState(null)
  const load = async () => { const next = await api(`/api/experiments/${id}`); setRun(next); if (next.status === 'completed') setResults(await api(`/api/experiments/${id}/results`)) }
  useEffect(() => { load(); if (run && !['queued','running'].includes(run.status)) return; const timer=window.setInterval(load,2000); return()=>window.clearInterval(timer) }, [id,run?.status])
  if (!run) return <div className="page-loading"><LoaderCircle className="spin" />Loading experiment</div>
  const progress = run.progress || {}
  const cancel = async () => { await api(`/api/experiments/${id}/cancel`, { method: 'POST' }); notify('Cancellation requested'); refresh(); load() }
  const openArtifact = async name => { setArtifact({name,loading:true}); try { setArtifact(await api(`/api/experiments/${id}/artifacts/${encodeURIComponent(name)}/preview`)) } catch(error) { setArtifact({name,error:error.message}) } }
  const targets = [...new Set((results?.metrics || []).map(row => row.target))]
  const selectedTarget = resultTarget || targets[0] || ''
  const targetMetrics = (results?.metrics || []).filter(row => !selectedTarget || row.target === selectedTarget)
  const targetHistory = (results?.history || []).filter(row => !selectedTarget || row.target === selectedTarget)
  const targetPredictions = (results?.predictions || []).filter(row => !selectedTarget || row.target === selectedTarget)
  const best = [...targetMetrics].sort((a,b) => Number(b.r2)-Number(a.r2))[0]
  const elapsed = progress.elapsed_seconds || (run.started_at && run.finished_at ? (new Date(run.finished_at)-new Date(run.started_at))/1000 : 0)
  return <div><button className="back-link" onClick={() => navigate('history')}><ArrowLeft size={16} />Experiment history</button><div className="run-heading"><div><div className="run-title-line"><h2>{run.name}</h2><Badge tone={statusTone(run.status)}>{run.status}</Badge></div><p>Experiment #{run.id} · started {fmtDate(run.started_at || run.created_at)}</p></div>{['queued','running'].includes(run.status) && <Button icon={CircleStop} variant="danger" onClick={cancel}>Cancel run</Button>}</div>
    <RunProgress run={run} progress={progress} elapsed={elapsed} />
    {results && <><TargetPredictabilityRanking rows={results.metrics||[]} onSelectTarget={setResultTarget}/><div className="results-toolbar"><div><p className="eyebrow">Target detail</p><h2>Inspect one predicted property</h2></div>{targets.length>1 && <label>Target property<Select ariaLabel="Choose target property" value={selectedTarget} onChange={setResultTarget} options={targets.map(target=>({value:target,label:target}))}/></label>}</div>
      {best && <div className="insight-grid"><MetricInsight label="Explained variance" value={`${(Number(best.r2)*100).toFixed(1)}%`} metric={`R² ${Number(best.r2).toFixed(3)}`} note="Higher is better; 100% means perfect predictions." tone="primary"/><MetricInsight label="Prediction correlation" value={Number(best.pearson).toFixed(3)} metric="Pearson r" note="How closely predictions follow the true trend."/><MetricInsight label="Normalized error" value={Number(best.mae_over_target_std).toFixed(3)} metric="MAE / target SD" note="Lower is better; below 1 beats predicting the mean."/><MetricInsight label="Best configuration" value={`${Math.round(Number(best.train_fraction)*100)}% · ${Number(best.epochs).toLocaleString()} ep.`} metric={`${best.embedding_model} · ${best.probe}`} note={`${Number(best.n_train).toLocaleString()} training interfaces.`}/></div>}
      <div className="chart-grid"><ResultLineChart title="Performance by training duration" eyebrow="Generalization" data={buildPerformanceChart(targetMetrics)} yLabel="Test R²" yDomain={['auto','auto']} /><ResultLineChart title="Optimization curves" eyebrow="Training loss" data={buildLearningChart(targetHistory)} yLabel="Normalized MSE" /><PredictionChart rows={targetPredictions} /></div>
      <MetricsTable rows={targetMetrics} />
    </>}
    <LogViewer run={run} showRaw={showRawLog} setShowRaw={setShowRawLog} onArtifact={openArtifact} />
    {artifact&&<ArtifactViewer artifact={artifact} experimentId={run.id} onClose={()=>setArtifact(null)}/>} 
  </div>
}
function RunProgress({run,progress,elapsed}) { const percent=run.status==='completed'?100:Math.max(0,Math.min(100,Number(progress.percent)||0));const active=['queued','running'].includes(run.status);const latest=progress.latest;return <section className="run-progress-panel"><div className="progress-main"><div className={`progress-state ${run.status}`}>{active?<LoaderCircle className="spin" size={18}/>:run.status==='completed'?<Check size={18}/>:<CircleStop size={18}/>}</div><div><span>{run.status==='completed'?'Run completed':run.status==='queued'?'Waiting for a worker':'Training in progress'}</span><strong>{Math.round(percent)}%</strong></div><div className="progress-time"><span>Elapsed</span><strong>{fmtDuration(elapsed)}</strong>{active&&progress.estimated_remaining_seconds?<small>about {fmtDuration(progress.estimated_remaining_seconds)} left</small>:run.finished_at?<small>finished {fmtDate(run.finished_at)}</small>:null}</div></div><div className="progress-track large"><span style={{width:`${percent}%`}}/></div><div className="progress-detail"><span><strong>{progress.completed||0}</strong> of <strong>{progress.expected||0}</strong> evaluations</span>{latest?<span>Latest: <strong>{latest.embedding_model}</strong> · {latest.target} · {Math.round(Number(latest.train_fraction)*100)}% data · {latest.epoch} epochs</span>:<span>Preparing data and model configuration…</span>}</div></section> }
function LogViewer({run,showRaw,setShowRaw,onArtifact}) { const lines=(run.log||'').split('\n').filter(Boolean);const events=lines.flatMap(line=>{if(!line.startsWith('STUDIO_PROGRESS '))return[];try{return[JSON.parse(line.slice(16))]}catch{return[]}});return <section className="panel log-panel"><div className="section-head"><div><p className="eyebrow">Execution</p><h2>Progress and outputs</h2></div><Button icon={showRaw?ChevronDown:ChevronRight} onClick={()=>setShowRaw(!showRaw)}>{showRaw?'Hide raw log':'Show raw log'}</Button></div>{events.length?<div className="log-events">{events.slice(-8).reverse().map((event,i)=><div key={i}><span className="event-dot"/><div><strong>{event.embedding_model} · {event.target}</strong><small>{event.probe} · {Math.round(Number(event.train_fraction)*100)}% data · {event.epoch} epochs</small></div><div><strong>R² {Number(event.r2).toFixed(3)}</strong><small>MAE {Number(event.mae).toFixed(2)} · {fmtDuration(event.elapsed_seconds)}</small></div></div>)}</div>:<div className="waiting-log"><LoaderCircle className={['queued','running'].includes(run.status)?'spin':''} size={18}/><span>{run.status==='queued'?'Waiting to start…':'No evaluation events were recorded.'}</span></div>}{showRaw&&<pre>{run.log||'Waiting for output…'}</pre>}<div className="artifact-grid">{run.artifacts.map(file=><div className="artifact-item" key={file}><button onClick={()=>onArtifact(file)}><File size={16}/><span>{file}</span><Eye size={15}/></button><a href={`/api/experiments/${run.id}/artifacts/${encodeURIComponent(file)}`} title={`Download ${file}`}><Download size={15}/></a></div>)}</div></section> }
function ArtifactViewer({artifact,experimentId,onClose}) { const download=`/api/experiments/${experimentId}/artifacts/${encodeURIComponent(artifact.name)}`;return <Modal title={artifact.name} subtitle={artifact.size_bytes!=null?`${(artifact.size_bytes/1024).toLocaleString(undefined,{maximumFractionDigits:1})} KB · ${artifact.type?.toUpperCase()||'Artifact'}`:'Loading artifact preview…'} onClose={onClose} width="1180px"><div className="artifact-viewer">{artifact.loading?<div className="page-loading"><LoaderCircle className="spin"/>Preparing preview</div>:artifact.error?<Empty icon={File} title="Preview unavailable" text={artifact.error} action={<a className="button button-primary" href={download}><Download size={16}/>Download file</a>}/>:artifact.type==='csv'?<CsvPreview artifact={artifact}/>:artifact.type==='json'?<JsonPreview value={artifact.value}/>:artifact.type==='log'?<LogPreview artifact={artifact}/>:null}</div><footer className="artifact-viewer-footer"><span>{artifact.truncated?'Showing a safe preview of this file. Download it to see every row or line.':'Complete file preview'}</span><a className="button button-primary" href={download}><Download size={16}/>Download</a></footer></Modal> }
function CsvPreview({artifact}) { const [query,setQuery]=useState(''),[page,setPage]=useState(0);const pageSize=50;const filtered=artifact.rows.filter(row=>!query||Object.values(row).some(value=>String(value??'').toLowerCase().includes(query.toLowerCase())));const pages=Math.max(1,Math.ceil(filtered.length/pageSize)),shown=filtered.slice(page*pageSize,(page+1)*pageSize);useEffect(()=>setPage(0),[query]);return <><div className="artifact-toolbar"><div className="search-field"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search preview rows"/></div><span>{filtered.length.toLocaleString()} preview rows · {artifact.columns.length} columns</span></div><div className="artifact-table"><table><thead><tr><th>#</th>{artifact.columns.map(column=><th key={column}>{column}</th>)}</tr></thead><tbody>{shown.map((row,i)=><tr key={i}><td>{page*pageSize+i+1}</td>{artifact.columns.map(column=><td key={column} title={String(row[column]??'')}>{formatArtifactCell(row[column])}</td>)}</tr>)}</tbody></table></div><div className="pagination"><Button icon={ArrowLeft} disabled={page===0} onClick={()=>setPage(page-1)}>Previous</Button><span>Page {page+1} of {pages}</span><Button disabled={page>=pages-1} onClick={()=>setPage(page+1)}>Next <ArrowRight size={15}/></Button></div></> }
function formatArtifactCell(value) { if(value==null)return'—';if(typeof value==='number')return Number.isInteger(value)?value.toLocaleString():value.toLocaleString(undefined,{maximumFractionDigits:5});return String(value) }
function JsonPreview({value}) { return <div className="json-preview"><JsonNode value={value} name="root" depth={0}/></div> }
function JsonNode({value,name,depth}) { if(value!==null&&typeof value==='object'){const entries=Array.isArray(value)?value.map((item,i)=>[i,item]):Object.entries(value);return <details open={depth<2}><summary><span className="json-key">{name}</span><span className="json-meta">{Array.isArray(value)?`Array(${entries.length})`:`Object(${entries.length})`}</span></summary><div className="json-children">{entries.map(([key,item])=><JsonNode key={key} name={String(key)} value={item} depth={depth+1}/>)}</div></details>}const type=value===null?'null':typeof value;return <div className="json-leaf"><span className="json-key">{name}</span><span className={`json-value ${type}`}>{value===null?'null':String(value)}</span></div> }
function LogPreview({artifact}) { const [query,setQuery]=useState('');const lines=artifact.lines.map((text,index)=>({number:index+1,text})).filter(line=>!query||line.text.toLowerCase().includes(query.toLowerCase()));return <><div className="artifact-toolbar"><div className="search-field"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search log lines"/></div><span>{lines.length.toLocaleString()} matching lines</span></div><div className="log-preview">{lines.map(line=><div className={line.text.startsWith('STUDIO_PROGRESS')?'progress-line':''} key={line.number}><span>{line.number}</span><code>{line.text}</code></div>)}</div></> }
function seriesKey(row) { return `${row.embedding_model} · ${row.probe} · ${Math.round(Number(row.train_fraction)*100)}% data` }
function pivotRows(rows, xKey, valueKey) { const map=new Map(); rows.forEach(row=>{const x=Number(row[xKey]);if(!map.has(x))map.set(x,{[xKey]:x});const value=Number(row[valueKey]);if(Number.isFinite(value))map.get(x)[seriesKey(row)]=value});return [...map.values()].sort((a,b)=>a[xKey]-b[xKey]) }
function buildPerformanceChart(metrics) { return pivotRows(metrics,'epochs','r2') }
function buildLearningChart(history) { return pivotRows(history.slice(0,1000),'epoch','train_mse_normalized') }
function buildTargetRanking(rows, embedding='all', probe='all') { const best=new Map;rows.filter(row=>(embedding==='all'||row.embedding_model===embedding)&&(probe==='all'||row.probe===probe)).forEach(row=>{const r2=Number(row.r2);if(!Number.isFinite(r2))return;const current=best.get(row.target);if(!current||r2>Number(current.r2))best.set(row.target,row)});return [...best.values()].sort((a,b)=>Number(b.r2)-Number(a.r2)) }
function compactTargetLabel(value) { return value.length>26?`${value.slice(0,11)}…${value.slice(-12)}`:value }
function TargetMetricChart({rows,title,dataKey,color,higherIsBetter=true}) { const values=rows.filter(row=>Number.isFinite(Number(row[dataKey]))),chartHeight=Math.max(500,values.length*25+54),domain=higherIsBetter?[value=>Math.min(0,value),value=>Math.max(1,value)]:[0,'auto'];return <article className={`ranking-metric-chart ${dataKey}`}><header><h3>{title}</h3><span>{higherIsBetter?'Higher is better':'Lower is better'}</span></header><div style={{height:chartHeight}}><ResponsiveContainer width="100%" height="100%"><BarChart data={values} layout="vertical" margin={{top:8,right:18,left:2,bottom:22}}><CartesianGrid stroke="#E3E7EC" horizontal={false}/><XAxis type="number" domain={domain} tickLine={false} axisLine={false} tick={{fontSize:9,fill:'#697180'}} label={{value:title,position:'insideBottom',offset:-10,fontSize:9,fill:'#697180'}}/><YAxis type="category" dataKey="target" width={142} tickFormatter={compactTargetLabel} tickLine={false} axisLine={false} tick={{fontSize:9,fill:'#343B48'}}/><Tooltip formatter={value=>[Number(value).toFixed(3),title]} labelFormatter={target=>`Target: ${target}`} cursor={{fill:'#F2F4F7'}}/><ReferenceLine x={0} stroke="#9AA1AC"/><Bar dataKey={dataKey} fill={color} radius={[0,3,3,0]} maxBarSize={15}/></BarChart></ResponsiveContainer></div></article> }
function SortableMetricHeader({label,metric,sort,setSort}) { const active=sort?.metric===metric,direction=active?sort.direction:null,Icon=direction==='asc'?ArrowUp:direction==='desc'?ArrowDown:ArrowUpDown;const toggle=()=>setSort(current=>current?.metric===metric?{metric,direction:current.direction==='desc'?'asc':'desc'}:{metric,direction:metric==='mae_over_target_std'?'asc':'desc'});return <th aria-sort={active?(direction==='asc'?'ascending':'descending'):'none'}><button className={active?'active':''} onClick={toggle}>{label}<Icon size={13}/></button></th> }
function TargetPredictabilityRanking({rows,onSelectTarget}) { const ranking=buildTargetRanking(rows),[sort,setSort]=useState({metric:'r2',direction:'desc'}),tableRows=useMemo(()=>{const direction=sort.direction==='asc'?1:-1;return[...ranking].sort((a,b)=>(Number(a[sort.metric])-Number(b[sort.metric]))*direction||String(a.target).localeCompare(String(b.target)))},[ranking,sort]);return <section className="panel target-ranking"><header className="ranking-title"><h2>Target feature analysis</h2></header>{ranking.length?<><div className="ranking-chart-grid"><TargetMetricChart rows={ranking} title="Test R²" dataKey="r2" color="#52679C"/><TargetMetricChart rows={ranking} title="Pearson r" dataKey="pearson" color="#56806A"/><TargetMetricChart rows={ranking} title="Normalized MAE" dataKey="mae_over_target_std" color="#B56F4F" higherIsBetter={false}/></div><div className="ranking-table"><table><thead><tr><th>#</th><th>Target</th><SortableMetricHeader label="Test R²" metric="r2" sort={sort} setSort={setSort}/><SortableMetricHeader label="Pearson" metric="pearson" sort={sort} setSort={setSort}/><SortableMetricHeader label="Normalized MAE" metric="mae_over_target_std" sort={sort} setSort={setSort}/></tr></thead><tbody>{tableRows.map((row,index)=><tr key={row.target}><td>{index+1}</td><td><button onClick={()=>onSelectTarget(row.target)}>{row.target}</button></td><td>{Number(row.r2).toFixed(3)}</td><td>{Number(row.pearson).toFixed(3)}</td><td>{Number(row.mae_over_target_std).toFixed(3)}</td></tr>)}</tbody></table></div></>:<ChartEmpty text="No finite test R² values are available."/>}</section> }
function MetricInsight({ label,value,metric,note,tone='' }) { return <article className={`metric-insight ${tone}`}><span>{label}</span><strong>{value}</strong><small>{metric}</small><p>{note}</p></article> }
function ResultLineChart({ title,eyebrow,data,yLabel,yDomain }) { const keys=data.length?Object.keys(data[0]).filter(key=>!['epoch','epochs'].includes(key)):[];const xKey=data[0]?.epoch!=null?'epoch':'epochs';return <section className="panel result-chart"><SectionHead eyebrow={eyebrow} title={title}/>{data.length?<ResponsiveContainer width="100%" height={280}><LineChart data={data} margin={{top:8,right:12,left:0,bottom:4}}><CartesianGrid stroke="#E8EAF0" vertical={false}/><XAxis dataKey={xKey} tickLine={false} axisLine={false} tick={{fontSize:11}} label={{value:'Epochs',position:'insideBottom',offset:-2,fontSize:11}}/><YAxis domain={yDomain} tickLine={false} axisLine={false} tick={{fontSize:11}} width={48}/><Tooltip formatter={(value)=>Number(value).toFixed(4)} labelFormatter={value=>`${value} epochs`}/><Legend wrapperStyle={{fontSize:11,paddingTop:12}}/>{keys.map((key,i)=><Line key={key} type="monotone" dataKey={key} stroke={['#4C5D8F','#8290B6','#2F3748','#A06A51','#69768D'][i%5]} strokeWidth={2} dot={{r:2}} activeDot={{r:4}}/>)}</LineChart></ResponsiveContainer>:<ChartEmpty text={`No ${yLabel.toLowerCase()} data was produced.`}/>}</section> }
function PredictionChart({ rows }) { const sample=rows.filter((_,i)=>i%Math.max(1,Math.floor(rows.length/900))===0).slice(0,900).map(row=>({actual:Number(row.y_true),predicted:Number(row.y_pred)})).filter(row=>Number.isFinite(row.actual)&&Number.isFinite(row.predicted));const under=sample.filter(x=>x.predicted<x.actual),over=sample.filter(x=>x.predicted>=x.actual);const values=sample.flatMap(x=>[x.actual,x.predicted]);const min=values.length?Math.min(...values):0,max=values.length?Math.max(...values):1;return <section className="panel result-chart prediction-chart"><SectionHead eyebrow="Calibration" title="Predicted vs. actual"/><p className="chart-description">Points on the diagonal are accurate. Blue points are under-predictions; orange points are over-predictions.</p>{sample.length?<ResponsiveContainer width="100%" height={330}><ScatterChart margin={{top:12,right:20,left:4,bottom:12}}><CartesianGrid stroke="#E8EAF0"/><XAxis type="number" dataKey="actual" name="Actual" domain={[min,max]} tick={{fontSize:11}} tickLine={false} label={{value:'Actual value',position:'insideBottom',offset:-8,fontSize:11}}/><YAxis type="number" dataKey="predicted" name="Predicted" domain={[min,max]} tick={{fontSize:11}} tickLine={false} width={56} label={{value:'Predicted value',angle:-90,position:'insideLeft',fontSize:11}}/><ZAxis range={[18,18]}/><Tooltip cursor={{strokeDasharray:'3 3'}} formatter={(value,name)=>[Number(value).toFixed(2),name]}/><Legend verticalAlign="top" height={30}/><ReferenceLine segment={[{x:min,y:min},{x:max,y:max}]} stroke="#242A36" strokeWidth={1.5} strokeDasharray="5 4" label={{value:'Perfect agreement',position:'insideTopRight',fontSize:10}}/><Scatter name="Under-predicted" data={under} fill="#4C5D8F" fillOpacity={.55}/><Scatter name="Over-predicted" data={over} fill="#C17652" fillOpacity={.55}/></ScatterChart></ResponsiveContainer>:<ChartEmpty text="No saved predictions are available for this run."/>}</section> }
function ChartEmpty({text}) { return <div className="chart-empty"><BarChart3 size={20}/><span>{text}</span></div> }
function MetricsTable({ rows }) { const columns=['embedding_model','probe','train_fraction','epochs','n_train','train_seconds','r2','pearson','mse','mae_over_target_std','mae','rmse'].filter(key=>rows.some(row=>key in row));const labels={embedding_model:'Embedding',train_fraction:'Training data',epochs:'Epochs',n_train:'Train samples',train_seconds:'Train time',r2:'R²',pearson:'Pearson r',mse:'MSE',mae_over_target_std:'Normalized MAE',mae:'MAE',rmse:'RMSE'};const format=(key,value)=>{const number=Number(value);if(key==='train_fraction')return`${Math.round(number*100)}%`;if(key==='train_seconds')return fmtDuration(number);if(['n_train','epochs'].includes(key))return number.toLocaleString();if(Number.isFinite(number))return number.toFixed(3);return value};return <section className="panel metrics-panel"><SectionHead eyebrow="All configurations" title="Evaluation metrics"/><div className="metric-guide"><span><strong>R² / Pearson:</strong> higher is better</span><span><strong>Errors:</strong> lower is better</span></div><div className="data-table"><table><thead><tr>{columns.map(key=><th key={key}>{labels[key]||key}</th>)}</tr></thead><tbody>{rows.slice(0,250).map((row,i)=><tr key={i}>{columns.map(key=><td key={key} className={key==='r2'?'metric-cell':''}>{format(key,row[key])}</td>)}</tr>)}</tbody></table></div></section> }
